package com.yeyamo_mobile.api.gamification_service.application;import static org.junit.jupiter.api.Assertions.*;import java.time.Instant;import java.util.*;import org.junit.jupiter.api.Test;import com.yeyamo_mobile.api.gamification_service.application.badge.MilestoneBadgeRule;import com.yeyamo_mobile.api.gamification_service.domain.Progress;
class MilestoneBadgeRuleTest{@Test void unlocksAllReachedMilestones(){var progress=new Progress("u",1600,5,7,7,null,Instant.now());var badges=new MilestoneBadgeRule().evaluate(progress,Map.of("POST",1L,"CHECKIN",5L,"SOCIAL",10L,"BOOKING",1L));assertEquals(Set.of("FIRST_POST","EXPLORER","TRAVELER_5","SOCIAL_10","FIRST_BOOKING","STREAK_7","LEVEL_5"),badges.stream().map(b->b.code()).collect(java.util.stream.Collectors.toSet()));}@Test void unlocksNothingForNewPlayer(){assertTrue(new MilestoneBadgeRule().evaluate(new Progress("u",0,1,0,0,null,Instant.now()),Map.of()).isEmpty());}}
